76	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
77	     */
78	    private static final Pattern EMAIL_PATTERN =
79	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
