130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
133	        rejectMissingOrBlankFields(ownerFieldsDto);
134	        HttpHeaders headers = new HttpHeaders();
135	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
136	        owner.setAddress(normalizeAddress(owner.getAddress()));
137	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
138	        owner.setEmail(normalizeEmail(owner.getEmail()));
139	        if (owner.getRegistrationDate() == null) {
140	            owner.setRegistrationDate(LocalDate.now());
141	        }
142	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
143	        rejectDuplicateTelephone(owner.getTelephone());
144	        rejectDuplicateEmail(owner.getEmail());
145	        rejectDailyLimitReached(owner.getRegistrationDate());
146	        rejectCityAtCapacity(owner.getCity());
147	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
148	            assignHousehold(owner);
149	        } else {
150	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
151	        }
152	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
153	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
154	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
155	        this.clinicService.saveOwner(owner);
156	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
157	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
158	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
159	        headers.setLocation(UriComponentsBuilder.newInstance()
160	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
161	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
162	    }
