253	            }
254	        }
255	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	    }
257	
258	    /**
259	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
260	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
261	     *
262	     * @param fields the submitted owner fields
263	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
264	     *                                        {@code null} or blank, or if address is blank after
265	     *                                        normalization
266	     */
267	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
268	        List<String> missing = new ArrayList<>();
269	        if (isBlank(fields.getFirstName())) {
270	            missing.add("firstName");
271	        }
272	        if (isBlank(fields.getLastName())) {
273	            missing.add("lastName");
274	        }
275	        if (isBlank(normalizeAddress(fields.getAddress()))) {
276	            missing.add("address");
277	        }
278	        if (isBlank(fields.getCity())) {
279	            missing.add("city");
280	        }
281	        if (isBlank(fields.getTelephone())) {
282	            missing.add("telephone");
283	        }
284	        if (!missing.isEmpty()) {
285	            throw new RequiredFieldsMissingException(missing);
286	        }
287	    }
288	
289	    private boolean isBlank(String value) {
290	        return value == null || value.isBlank();
291	    }
292	
293	    /**
294	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
295	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
296	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
297	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
298	     * <p>
299	     * Where a per-country rule is defined the national-number length is validated against the country
300	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
301	     * requires exactly 10.
302	     *
303	     * @param telephone the raw telephone value from the request
304	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
305	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
306	     */
307	    private String normalizeTelephone(String telephone) {
308	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
309	        String digits;
310	        if (cleaned.startsWith("+")) {
311	            digits = cleaned.substring(1);
312	        } else {
313	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
314	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
315	            digits = "61" + national;
316	        }
317	        if (!digits.matches("[0-9]{8,15}")) {
318	            throw new InvalidTelephoneException(cleaned);
319	        }
320	        // Validate the national-number length against the country code where a rule is defined.
321	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
322	            throw new InvalidTelephoneException(cleaned);
323	        }
324	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
325	            throw new InvalidTelephoneException(cleaned);
326	        }
327	        return "+" + digits;
328	    }
329	
330	    /**
331	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
332	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
333	     * lower-cased.
334	     *
335	     * @param email the raw email value from the request, or {@code null} if omitted
336	     * @return the lower-cased email, or {@code null} if none was supplied
337	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
338	     */
339	    private String normalizeEmail(String email) {
340	        if (email == null) {
341	            return null;
342	        }
343	        String trimmed = email.strip();
344	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
345	            throw new InvalidEmailException(email);
346	        }
347	        return trimmed.toLowerCase(Locale.ROOT);
348	    }
349	
350	    /**
351	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
352	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
353	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
354	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
355	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
356	     *
357	     * @param address the raw address value from the request (may be {@code null})
358	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
359	     */
360	    private String normalizeAddress(String address) {
361	        if (address == null) {
362	            return "";
363	        }
364	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
365	        if (collapsed.isEmpty()) {
366	            return "";
367	        }
368	        String[] tokens = collapsed.split(" ");
369	        StringBuilder sb = new StringBuilder(collapsed.length());
370	        for (int i = 0; i < tokens.length; i++) {
371	            if (i > 0) {
372	                sb.append(' ');
373	            }
374	            sb.append(expandAddressAbbreviation(tokens[i]));
375	        }
376	        return sb.toString();
377	    }
378	
379	    /**
380	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
381	     * returns the token unchanged when it is not a recognised abbreviation.
382	     *
383	     * @param token an upper-cased whole-word address token
384	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
385	     */
386	    private String expandAddressAbbreviation(String token) {
387	        return switch (token) {
388	            case "ST" -> "STREET";
389	            case "RD" -> "ROAD";
390	            case "AVE" -> "AVENUE";
391	            default -> token;
392	        };
393	    }
394	
395	    /**
396	     * Rejects a create request whose normalized telephone is already used by another owner. Owners store
397	     * their telephone in normalized E.164 form, so an exact string comparison of E.164 values is sufficient.
398	     *
399	     * @param telephone the normalized (E.164) telephone of the owner being created
400	     * @throws DuplicateTelephoneException if any existing owner already uses the telephone
401	     */
402	    /**
403	     * Builds the customer code assigned to a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
404	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3} the
405	     * upper-cased first three letters of the owner's last name, and {@code NNNN} a per-city 4-digit
406	     * zero-padded sequence equal to one more than the number of owners already in that city (e.g.
407	     * {@code 'SYD-SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes
408	     * it. Cities are matched case-insensitively so that owners sharing a {@code CITY3} prefix share a sequence.
409	     *
410	     * @param city the owner's city
411	     * @param lastName the owner's last name
412	     * @return the assigned customer code
413	     */
414	    private String generateCustomerCode(String city, String lastName) {
415	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
416	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
417	        int sequence = (int) this.clinicService.findAllOwners().stream()
418	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
419	            .count() + 1;
420	        return String.format("%s-%s-%04d", city3, last3, sequence);
421	    }
422	
423	    /**
424	     * Counts how many existing owners already share the given first name and last name, compared
425	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
426	     * owner being created.
427	     *
428	     * @param firstName the first name of the owner being created
429	     * @param lastName the last name of the owner being created
430	     * @return the number of existing owners with the same first and last name (case-insensitively)
431	     */
432	    private int countNamesakes(String firstName, String lastName) {
433	        return (int) this.clinicService.findAllOwners().stream()
434	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
435	                && lastName.equalsIgnoreCase(existing.getLastName()))
436	            .count();
437	    }
438	
439	    /**
440	     * The maximum number of owners permitted in a single city. A create request whose city already
441	     * holds this many owners is rejected.
442	     */
443	    private static final int CITY_OWNER_LIMIT = 50;
444	
445	    /**
446	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
447	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
448	     * differing only in the casing of their city share one capacity pool. The count is taken before the
449	     * new owner is persisted, so it excludes the owner being created.
450	     *
451	     * @param city the city of the owner being created
452	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
453	     */
454	    private void rejectCityAtCapacity(String city) {
455	        long existing = this.clinicService.findAllOwners().stream()
456	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
457	            .count();
458	        if (existing >= CITY_OWNER_LIMIT) {
459	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
460	        }
461	    }
462	
463	    /**
464	     * The maximum number of owners permitted to be created in a single day. A create request whose
465	     * registration date already holds this many owners is rejected.
466	     */
467	    private static final int DAILY_OWNER_LIMIT = 100;
468	
469	    /**
470	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
471	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
472	     * persisted, so it excludes the owner being created.
473	     *
474	     * @param registrationDate the registration date of the owner being created
475	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
476	     */
477	    /**
478	     * Adjusts an effective registration date so that it always falls on a business day. When the given
479	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
480	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
481	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
482	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
483	     * business-day-adjusted date.
484	     *
485	     * @param date the effective registration date, supplied or defaulted
486	     * @return the same date when it is a weekday, otherwise the next Monday
487	     */
488	    private LocalDate rollToBusinessDay(LocalDate date) {
489	        DayOfWeek day = date.getDayOfWeek();
490	        if (day == DayOfWeek.SATURDAY) {
491	            return date.plusDays(2);
492	        }
493	        if (day == DayOfWeek.SUNDAY) {
494	            return date.plusDays(1);
495	        }
496	        return date;
497	    }
498	
499	    /**
500	     * The number of owners that must already exist for a given day before a further create is flagged as a
501	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
502	     * the created owner carries {@code bulkSignupWarning = true}.
503	     */
504	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
505	
506	    /**
507	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
508	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
509	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
510	     * the daily create-limit rule's accumulation path.
511	     *
512	     * @param registrationDate the registration date of the owner being created
513	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
514	     */
515	    private boolean isBulkSignupDay(LocalDate registrationDate) {
516	        long existing = this.clinicService.findAllOwners().stream()
517	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
518	            .count();
519	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
520	    }
521	
522	    private void rejectDailyLimitReached(LocalDate registrationDate) {
523	        long existing = this.clinicService.findAllOwners().stream()
524	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
525	            .count();
526	        if (existing >= DAILY_OWNER_LIMIT) {
527	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
528	        }
529	    }
530	
531	    private void rejectDuplicateTelephone(String telephone) {
532	        boolean taken = this.clinicService.findAllOwners().stream()
533	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
534	        if (taken) {
535	            throw new DuplicateTelephoneException(telephone);
536	        }
537	    }
538	
539	    /**
540	     * Rejects a create request whose email is already used by another owner. Email is optional, so a
541	     * {@code null} email (none supplied) is never a duplicate. Owners store their email in normalized
542	     * (lower-cased) form, so an exact string comparison of the lower-cased values is sufficient.
543	     *
544	     * @param email the normalized (lower-cased) email of the owner being created, or {@code null} if none
545	     * @throws DuplicateEmailException if any existing owner already uses the email
546	     */
547	    private void rejectDuplicateEmail(String email) {
548	        if (email == null) {
549	            return;
550	        }
551	        boolean taken = this.clinicService.findAllOwners().stream()
552	            .anyMatch(existing -> email.equals(existing.getEmail()));
553	        if (taken) {
554	            throw new DuplicateEmailException(email);
555	        }
556	    }
557	
558	    /**
559	     * Rejects a create request whose owner shares both last name and address with an existing owner.
560	     * Last name and address are compared case-insensitively with runs of whitespace collapsed to a
561	     * single space and leading/trailing whitespace removed, so cosmetic differences (extra spaces,
562	     * differing case) still count as the same household.
563	     *
564	     * @param lastName the last name of the owner being created
565	     * @param address the address of the owner being created
566	     * @throws DuplicateHouseholdException if an existing owner has the same last name and address
567	     */
568	    private void rejectDuplicateHousehold(String lastName, String address) {
569	        String normalizedLastName = normalizeForComparison(lastName);
570	        String normalizedAddress = normalizeForComparison(address);
571	        boolean taken = this.clinicService.findAllOwners().stream()
572	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
573	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
574	        if (taken) {
575	            throw new DuplicateHouseholdException(lastName, address);
576	        }
577	    }
578	
579	    /**
580	     * Assigns the owner being created into a shared household. When at least one existing owner has the
581	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
582	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
583	     * reused when present; otherwise a deterministic id derived from the household's last name and address
584	     * is minted, so independently created members of the same household converge on one value. When no
585	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
586	     *
587	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
588	     */
589	    private void assignHousehold(Owner owner) {
590	        String normalizedLastName = normalizeForComparison(owner.getLastName());
591	        String normalizedAddress = normalizeForComparison(owner.getAddress());
592	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
593	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
594	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
595	            .toList();
596	        if (housemates.isEmpty()) {
597	            return;
598	        }
599	        String householdId = housemates.stream()
600	            .map(Owner::getHouseholdId)
601	            .filter(id -> id != null && !id.isBlank())
602	            .findFirst()
603	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
604	        owner.setHouseholdId(householdId);
605	        for (Owner housemate : housemates) {
606	            if (!householdId.equals(housemate.getHouseholdId())) {
607	                housemate.setHouseholdId(householdId);
608	                this.clinicService.saveOwner(housemate);
609	            }
610	        }
611	    }
612	
613	    /**
614	     * Derives a stable household identifier from the normalized last name and address of a household, as
615	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
616	     * deterministic, so any owner independently joining the same household computes the same identifier.
617	     *
618	     * @param normalizedLastName the household's last name, already normalized for comparison
619	     * @param normalizedAddress the household's address, already normalized for comparison
620	     * @return a stable, shareable household identifier
621	     */
622	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
623	        String key = normalizedLastName + "|" + normalizedAddress;
624	        try {
625	            byte[] digest = MessageDigest.getInstance("SHA-256")
626	                .digest(key.getBytes(StandardCharsets.UTF_8));
627	            StringBuilder sb = new StringBuilder(digest.length * 2);
628	            for (byte b : digest) {
629	                sb.append(String.format("%02x", b));
630	            }
631	            return sb.substring(0, 16);
632	        } catch (NoSuchAlgorithmException e) {
633	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
634	        }
635	    }
636	
637	    /**
638	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
639	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
640	     * lower-cased.
641	     *
642	     * @param value the raw value to normalize (may be {@code null})
643	     * @return the normalized value, or an empty string when {@code value} is {@code null}
644	     */
645	    private String normalizeForComparison(String value) {
646	        if (value == null) {
647	            return "";
648	        }
649	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
650	    }
651	}
